begin;
create extension if not exists pgtap with schema extensions;
select plan(19);
select ok((select relrowsecurity from pg_class where oid='public.treatment_plans'::regclass),'plans have RLS');
select ok(not has_table_privilege('authenticated','public.treatment_plans','insert'),'browser cannot insert plans');
insert into auth.users (id,email) values ('11111111-1111-1111-1111-111111111111','owner@example.test'),('22222222-2222-2222-2222-222222222222','dentist@example.test'),('33333333-3333-3333-3333-333333333333','reception@example.test'),('44444444-4444-8444-8444-444444444444','assistant@example.test');
insert into public.clinics (id,name,currency_code,time_zone,created_by) values ('aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Demo','RUB','Europe/Moscow','11111111-1111-1111-1111-111111111111');
insert into public.clinic_members (id,clinic_id,user_id,email) values ('cccccccc-cccc-cccc-cccc-cccccccccccc','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','22222222-2222-2222-2222-222222222222','dentist@example.test'),('dddddddd-dddd-dddd-dddd-dddddddddddd','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','33333333-3333-3333-3333-333333333333','reception@example.test'),('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','44444444-4444-8444-8444-444444444444','assistant@example.test');
insert into public.clinic_member_roles (clinic_member_id,role,assigned_by) values ('cccccccc-cccc-cccc-cccc-cccccccccccc','dentist','11111111-1111-1111-1111-111111111111'),('dddddddd-dddd-dddd-dddd-dddddddddddd','receptionist','11111111-1111-1111-1111-111111111111'),('eeeeeeee-eeee-4eee-8eee-eeeeeeeeeeee','assistant','11111111-1111-1111-1111-111111111111');
insert into public.patients (id,clinic_id,patient_number,first_name,last_name,phone,birth_date_precision,created_by) values ('ffffffff-ffff-4fff-8fff-ffffffffffff','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','PAT-00001','Ada','Demo','+79990000000','unknown','11111111-1111-1111-1111-111111111111');
select lives_ok($$select public.procedure_create('11111111-1111-1111-1111-111111111111','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','{"name":"Crown","category":"Restoration","defaultPrice":5000,"durationMinutes":60}'::jsonb)$$,'owner creates a procedure');
select throws_ok($$select public.procedure_create('22222222-2222-2222-2222-222222222222','aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa','{"name":"Cleaning","category":"Hygiene","defaultPrice":1000,"durationMinutes":30}'::jsonb)$$,'P0001','treatment_plan_edit_forbidden','dentist cannot manage catalogue');
select lives_ok($$select public.treatment_plan_create('22222222-2222-2222-2222-222222222222','ffffffff-ffff-4fff-8fff-ffffffffffff','cccccccc-cccc-cccc-cccc-cccccccccccc','Plan')$$,'dentist creates draft');
select throws_ok($$select public.treatment_plan_transition('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff'),'active')$$,'P0001','treatment_plan_items_required','empty draft cannot activate');
select lives_ok($$select public.treatment_plan_item_add('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff'),jsonb_build_object('procedureId',(select id from public.procedures where clinic_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),'toothNumber',16,'estimatedPrice',5500))$$,'dentist adds item with price snapshot');
select is((select total_estimated_cost from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff'),5500::numeric,'server calculates total');
select lives_ok($$select public.treatment_plan_transition('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff'),'active')$$,'draft activates with item');
select lives_ok($$select public.treatment_plan_create('22222222-2222-2222-2222-222222222222','ffffffff-ffff-4fff-8fff-ffffffffffff','cccccccc-cccc-cccc-cccc-cccccccccccc',null)$$,'dentist may prepare a second draft');
select lives_ok($$select public.treatment_plan_item_add('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and status='draft'),jsonb_build_object('procedureId',(select id from public.procedures where clinic_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa')))$$,'second draft can receive an item');
select lives_ok($$select public.treatment_plan_item_update_draft('22222222-2222-2222-2222-222222222222',(select item.id from public.treatment_plan_items item join public.treatment_plans plan on plan.id=item.treatment_plan_id where plan.patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and plan.status='draft'),jsonb_build_object('procedureId',(select id from public.procedures where clinic_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),'description','First','estimatedPrice',4500))$$,'dentist updates a draft item');
select is((select total_estimated_cost from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and status='draft'),4500::numeric,'draft item update recalculates total');
select lives_ok($$select public.treatment_plan_item_add('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and status='draft'),jsonb_build_object('procedureId',(select id from public.procedures where clinic_id='aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'),'description','Second'))$$,'dentist adds another draft item');
select lives_ok($$select public.treatment_plan_items_reorder_draft('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and status='draft'),(select jsonb_agg(item.id order by item.sort_order desc) from public.treatment_plan_items item join public.treatment_plans plan on plan.id=item.treatment_plan_id where plan.patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and plan.status='draft'))$$,'dentist reorders all draft items');
select is((select item.description from public.treatment_plan_items item join public.treatment_plans plan on plan.id=item.treatment_plan_id where plan.patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and plan.status='draft' order by item.sort_order limit 1),'Second','reorder persists the requested order');
select throws_ok($$select public.treatment_plan_transition('22222222-2222-2222-2222-222222222222',(select id from public.treatment_plans where patient_id='ffffffff-ffff-4fff-8fff-ffffffffffff' and status='draft'),'active')$$,'P0001','treatment_plan_active_exists','only one active plan is allowed');
-- Preserve the legacy RLS behavior checks inside this rolled-back test only.
grant select on all tables in schema public to authenticated;
set local role authenticated; set local request.jwt.claim.sub='33333333-3333-3333-3333-333333333333';
select is((select count(*)::integer from public.treatment_plans),2,'receptionist can view plans');
select is((select count(*)::integer from public.treatment_plan_items),3,'receptionist can view plan items');
reset role; select * from finish(); rollback;
